void setUp(void) {}
void tearDown(void) {}

#ifdef HAVE_ROM
using marble_physics::Mem;
using marble_physics::PLAYER;

// player fields
static const uint8_t VX = 0x00, VY = 0x04, VZ = 0x08, PX = 0x0c, PY = 0x10, PZ = 0x14;
static const uint8_t ZONE = 0x1b, VISIBLE = 0x1c, SX = 0x1e, SY = 0x20, AIR = 0x36;
static const uint8_t MASKS = 0x38, ANIM = 0x5a, SHARDS = 0x62, SHARDS_ON = 0x67;
static const uint8_t MASK_BYTES = 30;
// piston fields
static const uint8_t T_TIMER = 0x02, T_CX = 0x04, T_CY = 0x05, T_TOP = 0x06, T_ANIM = 0x08;
static const uint8_t T_SCREEN = 0x0c;
static const uint16_t UP = 0xffff;
static const uint8_t TYPE_PISTON = 0x29, NPISTONS = 36;
static const uint32_t ARMED = 0x400760, TIMERS = 0x400764;
static const uint32_t OLD_X = 0x400684, OLD_Y = 0x400688;   // longs
static const uint32_t SCRATCH = 0x400690;                    // 10 words to 0x4006a2
static const uint32_t CELL_X = 0x400696, CELL_Y = 0x400698;  // words
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint32_t LIST = 0x4003bc, ENTRIES = 0x4001dc;  // draw list bytes, entries
static const uint8_t ENTRY_SIZE = 14, LIST_MAX = 31, LIST_END = 0xff;
static const uint8_t RACES = 6, RACE_AERIAL = 3;
static const int16_t SWEEP_STEP = 4;  // marble_mo.SWEEP_STEP
static const uint8_t ARM_ZONE = 4, OTHER_ZONE = 7;

static uint8_t ram[marble_physics::RAM_SIZE];

static uint32_t piston(uint8_t i) { return 0x401650 + 0x10 * i; }

static void loadRam(const MarblePistonSegment &seg) {
  memset(ram, 0, sizeof(ram));
  for (uint8_t i = 0; i < seg.nram; i++) {
    const MarblePistonRam &r = seg.ram[i];
    memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
  }
}

// draw list entry k in link order: type << 8 | index, -1 past the end
static int16_t entryAt(const Mem &m, uint8_t k) {
  if (k >= LIST_MAX || m.rb(LIST + k) == LIST_END) { return -1; }
  const uint32_t e = ENTRIES + ENTRY_SIZE * m.rb(LIST + k);
  return (int16_t)(m.rb(e) << 8 | m.rb(e + 1));
}

static uint8_t listedCount(const Mem &m, uint8_t type, uint8_t idx) {
  uint8_t n = 0;
  for (uint8_t k = 0; entryAt(m, k) >= 0; k++) { n += entryAt(m, k) == (type << 8 | idx); }
  return n;
}

// player frame header drawn from +0x5a (states 1, 2, 5, 9) and the shard overlay +0x62
static uint32_t playerHdr(const Mem &m) {
  const uint8_t st = marble_physics::state(m);
  const bool drawn = st == marble_physics::DIZZY || st == marble_physics::BROKEN ||
                     st == marble_physics::EATEN || st == marble_physics::DISSOLVING;
  return m.rb(PLAYER + VISIBLE) && drawn ? m.roml(m.rl(PLAYER + ANIM)) : 0;
}

static uint32_t shardHdr(const Mem &m) {
  return m.rb(PLAYER + VISIBLE) && m.rb(PLAYER + SHARDS_ON) ? m.roml(m.rl(PLAYER + SHARDS)) : 0;
}

static const char *playerDiff(const Mem &m, const MarblePistonTick &t) {
  if (marble_physics::x(m) != t.x) { return "player x"; }
  if (marble_physics::y(m) != t.y) { return "player y"; }
  if (marble_physics::z(m) != t.z) { return "player z"; }
  if (marble_physics::state(m) != t.state) { return "player state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "player vis"; }
  if (m.sw(PLAYER + SX) != t.sx || m.sw(PLAYER + SY) != t.sy) { return "player sx/sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "player anim"; }
  if (playerHdr(m) != t.frame_hdr) { return "player frame"; }
  if (shardHdr(m) != t.shard_hdr) { return "player shards"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "player mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  if (m.rb(ARMED) != t.armed) { return "0x400760"; }
  if (m.rl(TIMERS) != t.timers) { return "0x400764"; }
  for (uint8_t k = 0; k < 10; k++) {
    if (m.rw(SCRATCH + 2 * k) != t.scratch[k]) { return "cell scratch"; }
  }
  return nullptr;
}

// piston frame drawn: rl(anim cursor) while listed, else 0
static uint32_t pistonHdr(const Mem &m, uint8_t i) {
  return listedCount(m, TYPE_PISTON, i) ? m.roml(m.rl(piston(i) + T_ANIM)) : 0;
}

static const char *pistonDiff(const Mem &m, uint8_t i, const MarblePistonObj &s) {
  const uint32_t a = piston(i);
  if (m.rw(a + T_TIMER) != s.timer) { return "piston timer"; }
  if (m.rb(a + T_CX) != s.cx || m.rb(a + T_CY) != s.cy) { return "piston cell"; }
  if (m.sw(a + T_TOP) != s.top) { return "piston top"; }
  if (m.rl(a + T_ANIM) != s.cursor) { return "piston cursor"; }
  if (m.sw(a + T_SCREEN) != s.sx || m.sw(a + T_SCREEN + 2) != s.sy) { return "piston sx/sy"; }
  if (pistonHdr(m, i) != s.frame_hdr) { return "piston frame"; }
  return nullptr;
}

static const char *listDiff(const Mem &m, const MarblePistonSegment &seg,
                            const MarblePistonTick &t) {
  for (uint8_t k = 0; k < t.nlist; k++) {
    const MarblePistonEntry &e = seg.list[t.lfirst + k];
    if (entryAt(m, k) != (e.type << 8 | e.index)) { return "draw list"; }
  }
  return entryAt(m, t.nlist) < 0 ? nullptr : "draw list length";
}

// One main loop tick as marble_piston.py replays it: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (old camera still stored, as 0x13ee6), player 0x251de, every
// enemy, slots 0x12fd0, rng, the 0x26f3e sort.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const int16_t old = m.sw(marble_physics::CAMERA);
  if ((int16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);
}

static void test_replay_pistons(void) {
  for (uint8_t s = 0; s < MARBLE_PISTON_SEGMENTS; s++) {
    const MarblePistonSegment &seg = marble_piston_segments[s];
    loadRam(seg);
    Mem m(ram, seg.race);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarblePistonTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      const char *bad = playerDiff(m, t);
      int8_t which = -1;
      for (uint8_t i = 0; i < NPISTONS && !bad; i++) {
        bad = pistonDiff(m, i, t.p[i]);
        which = (int8_t)i;
      }
      if (!bad) {
        which = -1;
        bad = listDiff(m, seg, t);
      }
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "segment %d (race %d frame %u) tick %d: piston %d %s differs",
               s, seg.race, (unsigned)seg.frame, k, which, bad);
      TEST_FAIL_MESSAGE(msg);
    }
  }
}

// ---------------------------------------------------------------- race start path

// machine race start (marble.cpp beginRace) on a cleared work RAM
static void beginRace(uint8_t race) {
  memset(ram, 0, sizeof(ram));
  Mem m(ram, race);
  marble_physics::startRace(m, race);
  marble_camera::start(m, race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// a listed piston <=> armed and up, at most once
static void checkListed(const Mem &m, uint8_t race, int16_t cam) {
  for (uint8_t i = 0; i < NPISTONS; i++) {
    const uint8_t want = m.rb(ARMED) && m.rw(piston(i) + T_TIMER) == UP ? 1 : 0;
    if (listedCount(m, TYPE_PISTON, i) == want) { continue; }
    char msg[80];
    snprintf(msg, sizeof(msg), "race %d cam %d: piston %d up %d, draw list differs", race, cam, i,
             want);
    TEST_FAIL_MESSAGE(msg);
  }
}

// Race sweep (marble_piston.py sweep): race start, then the camera over the whole race in 4
// line steps, back, again, player idle in its start zone; every enemy runs each tick. The
// table never arms (no zone change), no piston is listed, objects within OBJS.
static void test_race_sweep(void) {
  for (uint8_t race = 0; race < RACES; race++) {
    beginRace(race);
    Mem m(ram, race);
    const int16_t top = (int16_t)m.romw(m.desc() + marble_physics::DESC_TOP);
    const int16_t range = (int16_t)m.romw(m.desc() + marble_physics::DESC_RANGE);
    const int16_t n = range / SWEEP_STEP + 1;
    uint32_t tick = 0;
    for (uint8_t pass = 0; pass < 3; pass++) {
      for (int16_t j = 0; j < n; j++) {
        const int16_t step = pass == 1 ? n - 1 - j : j;
        const int16_t cam = top + SWEEP_STEP * step;
        mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
        marble_video::VideoState v = {};
        TEST_ASSERT_TRUE(marble_drawlist::build(m, cam, 24, v) <= marble_video::OBJS);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(0, m.rb(ARMED), "0x400760 set without a zone change");
        checkListed(m, race, cam);
      }
    }
  }
}

// aerial race start, the player in zone 4, the table armed (0x186ac from the zone hook)
static Mem armedAerial(void) {
  beginRace(RACE_AERIAL);
  Mem m(ram, RACE_AERIAL);
  m.wb(PLAYER + ZONE, ARM_ZONE);
  marble_enemies::arm_186ac(m);
  return m;
}

// ticks until piston i is up (timers at most 220 ticks)
static void untilUp(Mem &m, uint8_t i) {
  for (uint16_t k = 0; k < 400 && m.rw(piston(i) + T_TIMER) != UP; k++) {
    marble_enemies::update(m);
    marble_drawlist::sort(m);
  }
  TEST_ASSERT_EQUAL_HEX16(UP, m.rw(piston(i) + T_TIMER));
}

// Arming: every entry gets its index, cell (0x24406/0x2442a), top (0x2444e), a timer; the
// variant table pointer is one of 0x243f6; the cell scratch holds the last piston's cell
// (0x1bb28 + 0x1bb50), as the rest of the arcade's player physics then reads it.
static void test_arm_scratch(void) {
  Mem m = armedAerial();
  TEST_ASSERT_EQUAL_UINT8(1, m.rb(ARMED));
  for (uint8_t i = 0; i < NPISTONS; i++) {
    const uint32_t a = piston(i);
    TEST_ASSERT_EQUAL_UINT8(i, m.rb(a));
    TEST_ASSERT_EQUAL_UINT8(m.romb(0x24406 + i), m.rb(a + T_CX));
    TEST_ASSERT_EQUAL_UINT8(m.romb(0x2442a + i), m.rb(a + T_CY));
    TEST_ASSERT_EQUAL_HEX16(m.romw(0x2444e + 2 * i), m.rw(a + T_TOP));
  }
  bool variant = false;
  for (uint8_t v = 0; v < 4; v++) { variant |= m.rl(TIMERS) == m.roml(0x243f6 + 4 * v); }
  TEST_ASSERT_TRUE(variant);

  const uint32_t last = piston(NPISTONS - 1);
  const uint16_t x = (uint16_t)(m.rb(last + T_CX) << 3), y = (uint16_t)(m.rb(last + T_CY) << 3);
  TEST_ASSERT_EQUAL_HEX16(x, m.rw(SCRATCH));
  TEST_ASSERT_EQUAL_HEX16(y, m.rw(SCRATCH + 2));
  TEST_ASSERT_EQUAL_HEX16(x >> 3, m.rw(CELL_X));
  TEST_ASSERT_EQUAL_HEX16(y >> 3, m.rw(CELL_Y));
  TEST_ASSERT_EQUAL_HEX16(x & 7, m.rw(0x40069e));
  TEST_ASSERT_EQUAL_HEX16(y & 7, m.rw(0x4006a0));
  TEST_ASSERT_EQUAL_HEX16((y & 7) >= (x & 7) ? 1 : 0, m.rw(0x4006a2));

  // armed again: no change (0x400760 set, player still in zone 4/5)
  static uint8_t before[marble_physics::RAM_SIZE];
  memcpy(before, ram, sizeof(ram));
  marble_enemies::arm_186ac(m);
  TEST_ASSERT_EQUAL_MEMORY(before, ram, sizeof(ram));
}

// player on piston i's cell: new cell = the piston's, old position (0x400684/8) at old cell
// (ocx, ocy), z word z, v (vx, vy)
static void placeOn(Mem &m, uint8_t i, int8_t dcx, int8_t dcy, uint16_t z, int32_t vx,
                    int32_t vy) {
  const uint32_t a = piston(i);
  const uint8_t cx = m.rb(a + T_CX), cy = m.rb(a + T_CY);
  m.ww(CELL_X, cx);
  m.ww(CELL_Y, cy);
  m.wl(OLD_X, (uint32_t)((cx + dcx) * 8 + 4) << 16);
  m.wl(OLD_Y, (uint32_t)((cy + dcy) * 8 + 4) << 16);
  m.wl(PLAYER + PX, (uint32_t)(cx * 8 + 4) << 16);
  m.wl(PLAYER + PY, (uint32_t)(cy * 8 + 4) << 16);
  m.wl(PLAYER + PZ, (uint32_t)z << 16);
  m.wl(PLAYER + VX, (uint32_t)vx);
  m.wl(PLAYER + VY, (uint32_t)vy);
  m.wl(PLAYER + VZ, 0);
  m.wb(PLAYER + AIR, 0);
}

// 0x1881c: a piston up on the new cell sends the player back to its old position; launch from
// its own cell at the top (vz, 12 px up, v halved, the first sign always plus, airborne);
// a wall when lower than top + 12 (v reversed); nothing else above; nothing when down.
static void test_contact(void) {
  static const uint8_t K = 4;
  static const int32_t V = 0x20000;
  Mem m = armedAerial();
  untilUp(m, K);
  const uint16_t top = m.rw(piston(K) + T_TOP);

  placeOn(m, K, 0, 0, top, V, V);
  const uint32_t ox = m.rl(OLD_X), oy = m.rl(OLD_Y);
  TEST_ASSERT_TRUE(marble_enemies::contact_1881c(m, PLAYER));
  TEST_ASSERT_EQUAL_HEX32(ox, m.rl(PLAYER + PX));
  TEST_ASSERT_EQUAL_HEX32(oy, m.rl(PLAYER + PY));
  TEST_ASSERT_EQUAL_HEX32(0x70000, m.rl(PLAYER + VZ));
  TEST_ASSERT_EQUAL_HEX32(((uint32_t)top << 16) + 0xc0000, m.rl(PLAYER + PZ));
  TEST_ASSERT_EQUAL_HEX32((V >> 1) + 0x6000, m.rl(PLAYER + VX));
  TEST_ASSERT_EQUAL_HEX32((V >> 1) + 0x6000, m.rl(PLAYER + VY));  // vx high word set: plus
  TEST_ASSERT_EQUAL_UINT8(2, m.rb(PLAYER + AIR));

  placeOn(m, K, -1, 0, top, V, -V);
  TEST_ASSERT_TRUE(marble_enemies::contact_1881c(m, PLAYER));
  TEST_ASSERT_EQUAL_HEX32((uint32_t)-V, m.rl(PLAYER + VX));
  TEST_ASSERT_EQUAL_HEX32((uint32_t)V, m.rl(PLAYER + VY));
  TEST_ASSERT_EQUAL_HEX32(m.rl(OLD_X), m.rl(PLAYER + PX));
  TEST_ASSERT_EQUAL_UINT8(0, m.rb(PLAYER + AIR));

  placeOn(m, K, -1, 0, (uint16_t)(top + 12), V, V);
  TEST_ASSERT_TRUE(marble_enemies::contact_1881c(m, PLAYER));
  TEST_ASSERT_EQUAL_HEX32((uint32_t)V, m.rl(PLAYER + VX));
  TEST_ASSERT_EQUAL_HEX32(m.rl(OLD_X), m.rl(PLAYER + PX));

  m.ww(piston(K) + T_TIMER, 1);
  placeOn(m, K, 0, 0, top, V, V);
  const uint32_t px = m.rl(PLAYER + PX);
  TEST_ASSERT_FALSE(marble_enemies::contact_1881c(m, PLAYER));
  TEST_ASSERT_EQUAL_HEX32(px, m.rl(PLAYER + PX));
  TEST_ASSERT_EQUAL_HEX32((uint32_t)V, m.rl(PLAYER + VX));
}

// Leaving zone 4/5 tears the table down: pistons up leave the draw list, timers, cells and
// tops 0, 0x400760 0; a race switch with pistons up starts as from a cleared work RAM.
static void test_teardown_and_switch(void) {
  Mem m = armedAerial();
  untilUp(m, 0);
  TEST_ASSERT_EQUAL_UINT8(1, listedCount(m, TYPE_PISTON, 0));
  m.wb(PLAYER + ZONE, OTHER_ZONE);
  marble_enemies::arm_186ac(m);
  TEST_ASSERT_EQUAL_UINT8(0, m.rb(ARMED));
  for (uint8_t i = 0; i < NPISTONS; i++) {
    const uint32_t a = piston(i);
    TEST_ASSERT_EQUAL_UINT8(0, listedCount(m, TYPE_PISTON, i));
    TEST_ASSERT_EQUAL_HEX16(0, m.rw(a + T_TIMER));
    TEST_ASSERT_EQUAL_HEX16(0, m.rw(a + T_TOP));
    TEST_ASSERT_EQUAL_UINT8(0, m.rb(a + T_CX));
  }

  Mem up = armedAerial();
  untilUp(up, 0);
  const uint8_t next = (RACE_AERIAL + 1) % RACES;
  beginRace(next);
  static uint8_t clean[marble_physics::RAM_SIZE];
  memcpy(clean, ram, sizeof(ram));
  beginRace(next);
  TEST_ASSERT_EQUAL_MEMORY(clean, ram, sizeof(ram));
  Mem n(ram, next);
  TEST_ASSERT_EQUAL_UINT8(0, n.rb(ARMED));
  for (uint8_t i = 0; i < NPISTONS; i++) { TEST_ASSERT_EQUAL_UINT8(0, listedCount(n, TYPE_PISTON, i)); }
}
#endif

int main(int argc, char **argv) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  RUN_TEST(test_replay_pistons);
  RUN_TEST(test_race_sweep);
  RUN_TEST(test_arm_scratch);
  RUN_TEST(test_contact);
  RUN_TEST(test_teardown_and_switch);
#endif
  return UNITY_END();
}
